import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"多端应用与现场交付","description":"","frontmatter":{},"headers":[],"relativePath":"apps/terminal/index.md","filePath":"apps/terminal/index.md"}'),s={name:"apps/terminal/index.md"};function i(p,t,h,n,l,m){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="多端应用与现场交付" tabindex="-1">多端应用与现场交付 <a class="header-anchor" href="#多端应用与现场交付" aria-label="Permalink to “多端应用与现场交付”">​</a></h1><blockquote><p>把系统送到手上、装到机器旁 —— 移动端、小程序、桌面端、上位机与离线协同。</p></blockquote><p>本类只讲<strong>端上技术与交付</strong>：扫码采集、离线存储与同步、自动更新、串口通信、打包分发。业务实现（MES 报工、仓储出入库、设备点检）分别归 <a href="/my-vitepress-site/apps/industrial/">工业数字化应用</a> 与 <a href="/my-vitepress-site/apps/business/">企业业务应用</a>，端侧只负责落地。</p><table tabindex="0"><thead><tr><th>子域</th><th>讲什么</th><th>文章</th></tr></thead><tbody><tr><td>移动端与手持终端</td><td>Android 原生、工业 PDA、扫描引擎与设备选型</td><td><a href="/my-vitepress-site/apps/terminal/pda-app.html">PDA 移动端应用开发</a> · <a href="/my-vitepress-site/apps/terminal/scanner-sdk.html">扫码采集与扫描引擎对接</a></td></tr><tr><td>小程序与轻应用</td><td>登录态、环境配置、审核发布、低端机性能</td><td><a href="/my-vitepress-site/apps/business/mini-program.html">微信小程序开发实践</a></td></tr><tr><td>桌面客户端</td><td>Electron 进程模型、自动更新、打包分发（Tauri 规划中）</td><td><a href="/my-vitepress-site/apps/terminal/electron-desktop.html">Electron 桌面客户端实践</a></td></tr><tr><td>上位机与设备交互</td><td>WPF/WinForms、串口网口通信、实时刷新</td><td><a href="/my-vitepress-site/apps/terminal/csharp-hmi.html">C# 上位机界面开发</a></td></tr><tr><td>离线与协同</td><td>本地优先存储、变更队列、冲突解决、端云一致</td><td><a href="/my-vitepress-site/apps/terminal/offline-first.html">离线优先设计</a> · <a href="/my-vitepress-site/apps/terminal/web-pda-sync.html">Web 与 PDA 协同</a></td></tr></tbody></table><h2 id="各端技术栈" tabindex="-1">各端技术栈 <a class="header-anchor" href="#各端技术栈" aria-label="Permalink to “各端技术栈”">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>主力语言</th><th>常用框架</th><th>本站取舍</th></tr></thead><tbody><tr><td>Android</td><td>Kotlin（存量为 Java）</td><td>Jetpack Compose / XML + View</td><td>工业 PDA 的唯一现实选择，厂商扫描 SDK 只提供 Android AAR</td></tr><tr><td>iOS</td><td>Swift（存量为 Objective-C）</td><td>SwiftUI / UIKit</td><td>制造业项目基本用不到，暂不单独立文</td></tr><tr><td>微信小程序</td><td>TypeScript / JavaScript + WXML + WXSS</td><td>原生小程序、Taro、uni-app</td><td>已有实践，见小程序子域</td></tr><tr><td>跨端 App</td><td>Dart（Flutter）· Vue（uni-app）· React（Taro）</td><td>自绘或原生桥接</td><td>适合通用产品；PDA 需自写原生插件，不推荐</td></tr><tr><td>桌面客户端</td><td>TypeScript（Electron）· Rust（Tauri）</td><td>Chromium + Node / 系统 WebView</td><td>Electron 已有实践，Tauri 规划中</td></tr><tr><td>上位机</td><td>C#</td><td>WPF / WinForms</td><td>工控现场生态最匹配</td></tr></tbody></table><p><strong>项目状态图例</strong>：✅ 已验证（有运行/测试证据） · 🔧 验证中/在建（代码存在，证据整理中） · 📋 规划中（尚未开始）</p><h2 id="📋-规划中" tabindex="-1">📋 规划中 <a class="header-anchor" href="#📋-规划中" aria-label="Permalink to “📋 规划中”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>text-manager 文本管理工具</td><td>📋 待验证整理</td><td>TypeScript + Tauri 桌面应用，代码已在 GitHub 公开，构建/运行/测试验证后补充为案例</td></tr></tbody></table><h2 id="📋-技术实践" tabindex="-1">📋 技术实践 <a class="header-anchor" href="#📋-技术实践" aria-label="Permalink to “📋 技术实践”">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/my-vitepress-site/apps/terminal/pda-app.html">PDA 移动端应用开发</a></td><td>扫码兼容、离线缓存与同步、弱网处理、现场接口设计与部署</td></tr><tr><td><a href="/my-vitepress-site/apps/terminal/scanner-sdk.html">扫码采集与扫描引擎对接</a></td><td>三条取码路线怎么选、统一桥接层、GS1 与 DPM 解析、去抖与业务幂等</td></tr><tr><td><a href="/my-vitepress-site/apps/business/mini-program.html">微信小程序开发实践</a></td><td>登录态与授权、后端接口联调、体验版与发布流程、常见审核与性能问题</td></tr><tr><td><a href="/my-vitepress-site/apps/terminal/electron-desktop.html">Electron 桌面客户端实践</a></td><td>主/渲染进程分工、自动更新、本地存储与托盘、与后端联调、打包分发</td></tr><tr><td><a href="/my-vitepress-site/apps/terminal/csharp-hmi.html">C# 上位机界面开发</a></td><td>WinForms/WPF 选型、串口与网口通信、实时数据刷新、业务系统对接、异常与日志</td></tr><tr><td><a href="/my-vitepress-site/apps/terminal/web-pda-sync.html">Web 与 PDA 数据协同</a></td><td>任务分发与回传、状态一致性、冲突处理、条码与二维码数据流</td></tr><tr><td><a href="/my-vitepress-site/apps/terminal/offline-first.html">离线优先的终端应用设计</a></td><td>本地优先存储、变更队列与增量同步、冲突解决策略、重连补偿</td></tr></tbody></table><hr><p>上一级：<a href="/my-vitepress-site/apps/">应用矩阵</a></p>',13)])])}const b=e(s,[["render",i]]);export{c as __pageData,b as default};
